enum Denomination:
    COIN_1, COIN_5, COIN_10, NOTE_50, NOTE_100

class Money:
    // maps a Denomination to its value, and helps compute change
    static field VALUE = {
        COIN_1: 1, COIN_5: 5, COIN_10: 10, NOTE_50: 50, NOTE_100: 100
    }

    static method valueOf(denomination):
        return VALUE[denomination]

    // greedy breakdown; a real machine also checks a coin/note bank
    static method breakInto(amount, availableDenoms):
        result = []
        for d in sortDescending(availableDenoms):
            while amount >= valueOf(d):
                result.add(d)
                amount -= valueOf(d)
        return (result, amount)   // amount > 0 means exact change failed
```
